<script setup lang="ts">
import {ref,watch} from 'vue'
import {useStorageText} from './text'
import type {StorageApi} from './api'
import type {Product,Item} from './types'
import StoragePhotos from './StoragePhotos.vue'
const props=defineProps<{api:StorageApi;disabled:boolean;again?:{item:Item;intentId:string;quantity:number}|null}>(),emit=defineEmits<{saved:[];error:[string]}>(),{t}=useStorageText()
const blank=()=>({productId:null as string|null,nameZh:'',nameEn:'',quantity:1,opened:false,source:'customer',photos:[] as string[],note:''})
const lines=ref([blank()]),accepted=ref(false),search=ref(''),results=ref<Product[]>([]),uploading=ref(0),saving=ref(false),active=ref(0);let generation=0
watch(search,async(value)=>{const g=++generation;try{const p=await props.api.get<Product[]>('/products?query='+encodeURIComponent(value));if(g===generation)results.value=p}catch(e){if(g===generation)emit('error',String(e))}},{immediate:true})
watch(()=>props.again,value=>{if(value)lines.value=[{...blank(),productId:value.item.snapshot.productId,nameZh:value.item.snapshot.nameZh,nameEn:value.item.snapshot.nameEn,source:value.item.source,quantity:value.quantity}]},{immediate:true})
function choose(product:Product){const l=lines.value[active.value];if(l){l.productId=product.id;l.nameZh=product.nameZh;l.nameEn=product.nameEn}}
async function save(){if(saving.value)return;saving.value=true;try{await props.api.command('/applications',{lines:lines.value,rulesAccepted:accepted.value,withdrawalId:props.again?.intentId??null,withdrawalItemId:props.again?.item.id??null});lines.value=[blank()];accepted.value=false;emit('saved')}catch(e){emit('error',String(e))}finally{saving.value=false}}
</script>
<template><form class="storage-panel" @submit.prevent="save"><fieldset :disabled="disabled||saving||uploading>0"><h2>{{t('apply')}}</h2><p v-if="again">{{t('againHint')}}</p><label>{{t('search')}}<input v-model="search" maxlength="120"></label><div class="storage-options"><button v-for="p in results" :key="p.id" type="button" :disabled="disabled" @click="choose(p)">{{p.nameZh||p.nameEn}} · {{p.nameEn}} · {{p.code}}</button></div><article v-for="(l,index) in lines" :key="index" class="storage-panel" @focusin="active=index"><strong>#{{index+1}}</strong><button v-if="lines.length>1" type="button" @click="lines.splice(index,1)">{{t('remove')}}</button><small v-if="l.productId">{{t('candidates')}}</small><button v-if="l.productId&&!again" type="button" @click="l.productId=null">{{t('newName')}}</button><label>{{t('nameZh')}}<input v-model="l.nameZh" :readonly="!!l.productId" maxlength="200"></label><label>{{t('nameEn')}}<input v-model="l.nameEn" :readonly="!!l.productId" maxlength="200"></label><label>{{t('quantity')}}<input v-model.number="l.quantity" type="number" min="1" :max="l.opened?1:10000" required></label><select v-model="l.opened" @change="l.opened&&(l.quantity=1)"><option :value="false">{{t('whole')}}</option><option :value="true">{{t('opened')}}</option></select><select v-model="l.source"><option value="store">{{t('store')}}</option><option value="customer">{{t('customer')}}</option></select><StoragePhotos v-model="l.photos" :api="api" :disabled="disabled" @busy="uploading=Math.max(0,uploading+($event?1:-1))" @error="emit('error',$event)"/><label>{{t('note')}}<textarea v-model="l.note" maxlength="2000"/></label></article><button type="button" :disabled="disabled||lines.length>=50||!!again" @click="lines.push(blank());active=lines.length-1">{{t('add')}}</button><label><input v-model="accepted" type="checkbox" required>{{t('accept')}}</label><button type="submit" :disabled="disabled||saving||uploading>0||!accepted||lines.some(l=>!l.photos.length||(!l.productId&&!l.nameZh.trim()&&!l.nameEn.trim()))">{{t('submit')}}</button></fieldset></form></template>
